import type Graphic from "../../Graphic.js";
import type FormTemplate from "../../form/FormTemplate.js";
import type FeatureLayer from "../../layers/FeatureLayer.js";
import type GeoJSONLayer from "../../layers/GeoJSONLayer.js";
import type OrientedImageryLayer from "../../layers/OrientedImageryLayer.js";
import type SceneLayer from "../../layers/SceneLayer.js";
import type KnowledgeGraphSublayer from "../../layers/knowledgeGraph/KnowledgeGraphSublayer.js";
import type SubtypeSublayer from "../../layers/support/SubtypeSublayer.js";
import type { FieldValue } from "../../layers/support/fieldUtils.js";

/**
 * The current state of the BatchAttributeForm.
 *
 * @since 5.0
 */
export type BatchAttributeFormState = "not-loaded" | "loading" | "failed" | "loaded";

/**
 * The mode of the form.
 *
 * @since 5.0
 */
export type BatchAttributeFormMode = "single" | "batch";

/**
 * An array of layers included in the [BatchAttributeForm](https://developers.arcgis.com/javascript/latest/references/core/widgets/BatchAttributeForm/). Each layer must support feature editing and field access.
 *
 * @since 5.0
 */
export type AttributeFormSupportedLayerUnion = FeatureLayer | GeoJSONLayer | OrientedImageryLayer | SceneLayer | SubtypeSublayer | KnowledgeGraphSublayer;

/**
 * Describes the state of a single feature's attribute values at the time of a form submission.
 *
 * @since 5.0
 */
export interface SubmitResult {
  /**
   * The feature described by this result object.
   *
   * @since 5.0
   */
  feature: Graphic;
  /**
   * The names of fields that have invalid values for this feature.
   *
   * @since 5.0
   */
  invalidFields: string[];
  /**
   * The updated attribute values for the feature.
   *
   * @since 5.0
   */
  values: Graphic["attributes"];
  /**
   * Staged attachment edits for this feature.
   *
   * @since 5.1
   */
  attachmentEdits?: PendingAttachmentEdits[];
  /**
   * The element ids of attachment elements that are currently invalid.
   *
   * @since 5.1
   */
  invalidAttachmentElementIds?: string[];
}

/**
 * Attachment edits staged for a single attachment element.
 *
 * @since 5.1
 */
export interface PendingAttachmentEdits {
  /**
   * The display label of the attachment element input.
   *
   * @since 5.1
   */
  label?: string | null;
  /**
   * The keywords value configured on the attachment element input.
   *
   * @since 5.1
   */
  keywords?: string;
  /**
   * Attachments staged to be added.
   *
   * @since 5.1
   */
  adds: AddAttachmentEdit[];
  /**
   * Attachments staged to be updated.
   *
   * @since 5.1
   */
  updates: UpdateAttachmentEdit[];
  /**
   * Attachments staged to be deleted.
   *
   * @since 5.1
   */
  deletes: DeleteAttachmentEdit[];
}

/**
 * Information about an individual attachment edit, used for adding, updating, or deleting attachments.
 *
 * @since 5.1
 */
export interface BaseAttachmentEdit {
  /**
   * The feature, `objectId` or `globalId` of the feature associated with the attachment.
   *
   * @since 5.1
   */
  feature: Graphic;
  /**
   * The content type of the attachment. For example, `'image/jpeg'`.
   *
   * @since 5.1
   */
  contentType?: string;
  /**
   * The unique globalId of the attachment.
   *
   * @since 5.1
   */
  globalId: string;
  /**
   * The keywords value for an individual attachment.
   *
   * @since 5.1
   */
  keywords?: string;
  /**
   * The name of the attachment.
   *
   * @since 5.1
   */
  name?: string;
}

/**
 * Information about a single attachment to be added.
 *
 * @since 5.1
 */
export interface AddAttachmentEdit extends BaseAttachmentEdit {
  /**
   * The raw attachment data.
   *
   * @since 5.1
   */
  data: Blob | File | string;
}

/**
 * Information about a single attachment to be updated.
 *
 * @since 5.1
 */
export interface UpdateAttachmentEdit extends BaseAttachmentEdit {
  /**
   * The raw attachment data.
   *
   * @since 5.1
   */
  data: Blob | File | string;
  /**
   * The unique identifier of the attachment.
   *
   * @since 5.1
   */
  id: number;
}

/**
 * Information about a single attachment to be deleted.
 *
 * @since 5.1
 */
export interface DeleteAttachmentEdit extends BaseAttachmentEdit {
  /**
   * The unique identifier of the attachment.
   *
   * @since 5.1
   */
  id: number;
}

/** @since 5.0 */
export interface SubmitEvent {
  /**
   * The name of the event.
   *
   * @since 5.0
   */
  name: "submit";
  /**
   * An array containing a result object for each feature in the form.
   *
   * @since 5.0
   */
  results: SubmitResult[];
  /**
   * Indicates whether the form is valid. This is `true` if all features in the form have valid attribute values, and `false` if any feature has at least one invalid attribute value.
   *
   * @since 5.0
   */
  valid: boolean;
}

/** @since 5.1 */
export interface AttachmentsChangeEvent {
  /**
   * The name of the event.
   *
   * @since 5.1
   */
  name: "attachments-change";
  /**
   * The feature whose attachment edits were updated.
   *
   * @since 5.1
   */
  feature: Graphic;
  /**
   * The current attachment edits for the updated feature.
   *
   * @since 5.1
   */
  attachmentEdits: PendingAttachmentEdits[];
  /**
   * Indicates whether the form is valid.
   *
   * @since 5.1
   */
  valid: boolean;
}

/**
 * Selected attachment reference information.
 *
 * @since 5.1
 */
export interface SelectedAttachmentIdentifier {}

export type ValueChangeActor = "user" | "expression";

/** @since 5.0 */
export interface ValueChangeEvent {
  /**
   * The features affected by the value change.
   *
   * @since 5.0
   */
  features: Graphic[];
  /**
   * The name of the field that was changed.
   *
   * @since 5.0
   */
  fieldName: string;
  /**
   * The name of the event.
   *
   * @since 5.0
   */
  name: "value-change";
  /**
   * The updated field value.
   *
   * @since 5.0
   */
  value: FieldValue;
}

/**
 * Describes a field value change event with per-feature change details.
 *
 * @since 5.1
 */
export interface ValuesChangeEvent {
  /**
   * The changed values for each affected feature.
   *
   * @since 5.1
   */
  data: ValuesChangeData[];
  /**
   * The field whose value was interactively changed. The
   * [event data](https://developers.arcgis.com/javascript/latest/references/core/widgets/BatchAttributeForm/types/#ValuesChangeData-changes)
   * may include changes to additional fields that were triggered by
   * expressions.
   *
   * For events where the source is expressions, this field will be undefined,
   * no field is interactively changed in these cases.
   *
   * @since 5.1
   */
  fieldName?: string;
  /**
   * The name of the event.
   *
   * @since 5.1
   */
  name: "values-change";
  /**
   * Indicates whether the root cause of the values changing.
   *
   * Value | Description
   * ------| -----------
   * "user" | The value changes originated from a user-initiated change. The event may include expression-driven changes that were triggered as a result of the change the user made.
   * "expression" | All value changes are the result of expressions evaluations, and the expressions were evaluated due to some condition other than a user-intiated value change. For example, the expressions were intially evaluated when the form was loaded.
   */
  source: ValueChangeActor;
}

/**
 * Describes all field changes applied to a single feature during a `values-change` event.
 *
 * @since 5.1
 */
export interface ValuesChangeData {
  /**
   * The feature whose values changed.
   *
   * @since 5.1
   */
  feature: Graphic;
  /**
   * The field-level changes that were applied to the feature.
   *
   * @since 5.1
   */
  changes: ValueChange[];
}

/**
 * Describes a single field change for a feature in a `values-change` event.
 *
 * @since 5.1
 */
export interface ValueChange {
  /**
   * The name of the field that changed.
   *
   * @since 5.1
   */
  fieldName: string;
  /**
   * The updated value for the field.
   *
   * @since 5.1
   */
  value: FieldValue;
}

/**
 * Configurations used for setting the layer's [FormTemplate](https://developers.arcgis.com/javascript/latest/references/core/form/FormTemplate/) within `BatchAttributeForm`.
 *
 * @since 5.0
 */
export interface AttributeFormSupportedLayerInfo {
  /**
   * The associated layer containing the fields to edit.
   *
   * @since 5.0
   */
  layer: AttributeFormSupportedLayerUnion;
  /**
   * A template that defines the feature's form content. Use this when setting the fields for editing.
   *
   * @since 5.0
   */
  formTemplate?: FormTemplate;
}

/**
 * Types of layers that support Utility Network associations.
 *
 * @internal
 */
export type AssociationsLayerUnion = FeatureLayer | SubtypeSublayer;

/**
 * Configuration information needed to render buttons in the BatchAttributeForm footer.
 *
 * @internal
 */
export interface FooterButtonInfo {}

/**
 * Valid types of pages that can be displayed by the Batch Attribute Form.
 *
 * @internal
 */
export type Page = "default" | "viewing-attachments" | "viewing-attachment-details" | "replacing-attachment" | "adding-attachments" | "viewing-associated-layers" | "viewing-associated-features" | "viewing-related-records" | "viewing-related-categories";

/**
 * Configuration information about a selected attachment. Used to display details about the attachment.
 *
 * @internal
 */
export interface SelectedAttachmentDetails {}